export function computeInvoice(input) {
  const { lines, discountKobo = 0 } = input ?? {};

  if (!Array.isArray(lines)) {
    throw new RangeError("lines must be an array");
  }
  if (!Number.isInteger(discountKobo) || discountKobo < 0) {
    throw new RangeError("discountKobo must be a non-negative integer");
  }

  // BigInt keeps all monetary calculations and intermediate products exact.
  const entries = [];
  let subtotal = 0n;

  for (let index = 0; index < lines.length; index += 1) {
    const { sku, unitPriceKobo, qty, vatExempt } = lines[index] ?? {};

    if (!Number.isInteger(unitPriceKobo) || unitPriceKobo < 0) {
      throw new RangeError("unitPriceKobo must be a non-negative integer");
    }
    if (!Number.isInteger(qty) || qty < 1) {
      throw new RangeError("qty must be a positive integer");
    }

    const lineSubtotal = BigInt(unitPriceKobo) * BigInt(qty);
    subtotal += lineSubtotal;

    entries.push({
      sku,
      vatExempt,
      index,
      subtotal: lineSubtotal,
      discount: 0n,
      remainder: 0n,
    });
  }

  const requestedDiscount = BigInt(discountKobo);
  const appliedDiscount =
    requestedDiscount < subtotal ? requestedDiscount : subtotal;

  if (subtotal > 0n && appliedDiscount > 0n) {
    let allocated = 0n;

    for (const entry of entries) {
      const numerator = appliedDiscount * entry.subtotal;
      entry.discount = numerator / subtotal;
      entry.remainder = numerator % subtotal;
      allocated += entry.discount;
    }

    let remaining = appliedDiscount - allocated;

    if (remaining > 0n) {
      const ranked = entries.slice().sort((a, b) => {
        if (a.remainder === b.remainder) {
          return a.index - b.index;
        }
        return a.remainder > b.remainder ? -1 : 1;
      });

      for (let index = 0; remaining > 0n; index += 1) {
        ranked[index].discount += 1n;
        remaining -= 1n;
      }
    }
  }

  let vat = 0n;
  const resultLines = entries.map((entry) => {
    const net = entry.subtotal - entry.discount;

    // 7.5% = 3/40; adding half the denominator gives half-up rounding.
    const lineVat =
      entry.vatExempt === false ? (net * 3n + 20n) / 40n : 0n;

    vat += lineVat;

    return {
      sku: entry.sku,
      subtotalKobo: Number(entry.subtotal),
      discountKobo: Number(entry.discount),
      netKobo: Number(net),
      vatKobo: Number(lineVat),
    };
  });

  return {
    subtotalKobo: Number(subtotal),
    discountKobo: Number(appliedDiscount),
    vatKobo: Number(vat),
    totalKobo: Number(subtotal - appliedDiscount + vat),
    lines: resultLines,
  };
}
